from collections import deque

def find_components(grid):
    """Find all connected components with their bounding boxes"""
    h, w = len(grid), len(grid[0])
    visited = set()
    components = {}

    def bfs(start_pos, color):
        q = deque([start_pos])
        visited.add(start_pos)
        cells = [start_pos]

        while q:
            r, c = q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == color and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
                        cells.append((nr, nc))
        return cells

    color_idx = {}
    comp_idx = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                color = grid[r][c]
                if color not in color_idx:
                    color_idx[color] = comp_idx
                    comp_idx += 1
                cid = color_idx[color]
                if (r, c) not in visited:
                    cells = bfs((r, c), color)
                    bb_r = min(x[0] for x in cells)
                    bb_c = min(x[1] for x in cells)
                    bb_h = max(x[0] for x in cells) - bb_r + 1
                    bb_w = max(x[1] for x in cells) - bb_c + 1

                    components[(color, cid)] = {
                        'cells': cells,
                        'bb': (bb_r, bb_c, bb_h, bb_w),
                        'count': len(cells)
                    }

    return components, color_idx

